    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Quarto individual (privativo). Banheiro privativo (en-suite). Regime de meia pensão: café da manhã e jantar de segunda a sexta; pensão completa nos fins de semana. Inclui: roupa de cama, toalhas, limpeza semanal e acesso à internet/facilidades de TI. Categoria premium dentro da opção homestay.</p><p>Suplementos e condições: Suplemento de alta temporada: GBP 15/semana (24/mai a 15/ago/2026); Suplemento dieta especial: GBP 30/semana; Noite extra: GBP 50; Outro suplemento: GBP 50.</p><p>O preço base é o de baixa temporada (4/jan a 23/mai/2026 e 16/ago/2026 a 3/jan/2027); na alta temporada (24/mai a 15/ago/2026) acrescente £15 por semana. Taxa de reserva da acomodação £40, cobrada uma única vez. Noite extra £50 na baixa temporada e £55 na alta. Taxa de dieta especial £30 por semana (cobre intolerância à lactose, vegetariano e sem glúten). Suplemento de Natal £50 por semana para quem fica entre 20/12/2026 e 3/1/2027 (não se aplica na alta temporada). Taxa para manter o quarto reservado durante viagens £80 por semana. Taxa de cancelamento ou troca de família £100. Quarto individual para 16 e 17 anos custa £205 por semana na baixa e £250 na alta temporada. Estadias de domingo a domingo. Fonte: ETC Adult Dates and Fees 2026 (01/09/2025).</p>','["Homestay executivo com família anfitriã britânica selecionada pela ETC; inclui acesso a internet e facilidades de TI para quem precisa estudar ou trabalhar remotamente; ambiente tranquilo e privado.", "Ideal para adultos 18+ que querem homestay com banheiro privativo"]'::jsonb,'["Menos indicado para quem tem orçamento reduzido"]'::jsonb);
