    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Família anfitriã da LSI New York, cuidadosamente selecionada para oferecer um ambiente acolhedor e seguro; ótima oportunidade para praticar o idioma no dia a dia e vivenciar a cultura local.</p><p>Suplementos e condições: Suplemento de alta temporada: GBP 40/semana (24/mai a 15/ago/2026); Suplemento dieta especial: GBP 30/semana; Noite extra: GBP 35; Outro suplemento: GBP 50.</p><p>O preço base é o de baixa temporada (4/jan a 23/mai/2026 e 16/ago/2026 a 3/jan/2027); na alta temporada (24/mai a 15/ago/2026) acrescente £40 por semana. Taxa de reserva da acomodação £40, cobrada uma única vez. Noite extra £35 na baixa temporada e £45 na alta. Taxa de dieta especial £30 por semana (cobre intolerância à lactose, vegetariano e sem glúten). Suplemento de Natal £50 por semana para quem fica entre 20/12/2026 e 3/1/2027 (não se aplica na alta temporada). Taxa para manter o quarto reservado durante viagens £80 por semana. Taxa de cancelamento ou troca de família £100. Quarto individual para 16 e 17 anos custa £205 por semana na baixa e £250 na alta temporada. Estadias de domingo a domingo. Fonte: ETC Adult Dates and Fees 2026 (01/09/2025).</p>','["Anfitriões Licenciados", "Ideal para quem quer vivenciar a cultura britânica e praticar inglês em casa"]'::jsonb,'["Menos indicado para quem busca banheiro privativo garantido"]'::jsonb);
