    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Quarto compartilhado (tipo twin, com outro estudante). Banheiro privativo (en-suite: chuveiro, pia e vaso sanitário). Sem plano de refeições incluído por padrão (opção de café da manhã disponível como upgrade). Inclui: roupa de cama, serviço de lavanderia, limpeza semanal do quarto e Wi-Fi. Não inclui: refeições. Depósito de caução (cartão de crédito) exigido na chegada.</p><p>Suplementos e condições: Depósito caução (reembolsável): GBP 200.</p><p>A escola não publica ajuste sazonal nem suplementos para a residência na tabela Adult Dates and Fees 2026 — o valor final é confirmado no orçamento (price calculator) da ETC. É exigida uma autorização de cartão de crédito de £200 na chegada como caução (ou alternativa combinada com a escola) e o pagamento antecipado de uma semana de acomodação no ato da reserva. Estadias de sábado a sábado ou de domingo a domingo. Quartos com banheiro privativo, roupa de cama, limpeza semanal e Wi-Fi inclusos; no verão a escola também usa residências parceiras (apartamentos self-catering de 5 a 9 quartos, todos com banheiro privativo). Transfer privativo do aeroporto, somente ida, para 1 pessoa: Heathrow £180, Gatwick £200, Luton £220, Stansted £270, Bournemouth £45, Southampton £100 e Londres centro £260; check-in assistido £50 e espera £30 por hora. Fonte: etc-inter.net/residence e ETC Adult Dates and Fees 2026.</p>','["Residência da ETC localizada ao lado do campus em Bournemouth, com capacidade para até 60 estudantes internacionais; lounge estudantil com TV e jogos, Wi-Fi gratuito, CCTV e equipe no local; quarto com cama, guarda-roupa, cômoda e aquecimento central.", "Ideal para quem viaja com amigos e quer dividir custos com conforto"]'::jsonb,'["Menos indicado para quem prefere imersão com família local"]'::jsonb);
    insert into price_template (tenant_id, campus_id, name, price_basis, duration_type, unit, currency, charge_in_tiers, valid_from, status) values (v_tid,'1e52299a-af6a-5cad-a327-08cd9a10b062','Residência estudantil — quarto compartilhado, banheiro privativo, sem refeições','duration','flexible','week','GBP',false,'2026-01-01','active') returning id into v_tpl;
